// Ported from the Node app's Sequelize model BehaviorRecord (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class BehaviorRecordConfiguration : IEntityTypeConfiguration<BehaviorRecord>
{
    public void Configure(EntityTypeBuilder<BehaviorRecord> builder)
    {
        builder.ToTable("behavior_records", t =>
        {
            t.HasCheckConstraint("CK_behavior_records_type", "[type] IN (N'merit', N'demerit', N'incident', N'note')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.Type).HasColumnName("type").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(120)").HasMaxLength(120).IsRequired();
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.Points).HasColumnName("points").HasDefaultValueSql("0");
        builder.Property(e => e.RecordedBy).HasColumnName("recorded_by");
        builder.Property(e => e.RecordedByName).HasColumnName("recorded_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.HasOne(e => e.Student).WithMany(p => p.BehaviorRecords).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
